const write=(slug,html)=>{const dir=path.join(root,slug);fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'index.html'),html)};
const link=(p,slug)=>p+slug+'/';
function header(p) {
 const mega=groups.map(([label,slug,children])=>`<div><a class="mega-title" href="${link(p,slug)}">${label}</a>${children.map(s=>`<a href="${link(p,s)}">${esc(collections[s]?.title||s)}</a>`).join('')}</div>`).join('');
 return `<div class="announcement">Little moments. Big happiness. · Personalised gifts & thoughtful supplies</div><header class="header"><div class="wrap nav-row"><a class="brand" href="${p}" aria-label="Hamperia Solutions home"><img class="brand-logo" src="${p}assets/logo.png" alt="" width="58" height="58"><span class="brand-name">Hamperia<small>SOLUTIONS</small></span></a><button class="menu" aria-controls="navigation" aria-expanded="false" type="button">Menu ☰</button><nav class="nav-links" id="navigation" aria-label="Main navigation"><a href="${p}">Home</a><a href="${p}hamperia/">Hamperia Store</a><a href="${p}hampers/">Personalised Hampers</a><details class="corporate-menu"><summary>Corporate & Bulk Gifting</summary><div class="mega-menu"><a class="mega-overview" href="${p}corporate-bulk-gifting/">Explore corporate & bulk gifting →</a><div class="mega-grid">${mega}</div></div></details><a href="${p}tutorials/">Learn to Make</a><a href="${p}blog/">Blog</a></nav><div class="auth-controls" aria-label="Account"><a class="auth-link auth-guest" href="${p}auth/">Sign in</a><details class="auth-user profile-menu" hidden><summary class="profile-trigger"><svg aria-hidden="true" viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="8" r="3.3"></circle><path d="M5.5 20c.6-3.5 3-5.5 6.5-5.5s5.9 2 6.5 5.5"></path></svg><span class="auth-user-name" aria-label="Signed in as"></span><span class="profile-chevron" aria-hidden="true">⌄</span></summary><div class="profile-dropdown"><a data-auth-dashboard href="${p}account/">My account</a><button data-signout type="button">Sign out</button></div></details></div></div></header>`;
}
function footer(p){return `<footer class="footer"><div class="wrap"><div class="footer-top"><div><h2>Made to mean more.</h2><p>Personalised hampers, creative supplies and thoughtful corporate gifts.</p><p class="footer-browse"><a href="${p}">Home</a> · <a href="${p}hamperia/">Hamperia Store</a> · <a href="${p}hampers/">Personalised Hampers</a> · <a href="${p}corporate-bulk-gifting/">Corporate gifting</a></p></div><div class="footer-contact"><a href="mailto:contact@hamperiasolutions.com">contact@hamperiasolutions.com</a><p><a href="${p}bulk-orders/">Request a quotation</a> · <a href="${p}blog/">Ideas & guides</a></p></div></div><div class="footer-bottom"><span>© 2026 Hamperia Solutions</span><span>Little moments. Big happiness.</span></div></div></footer>`}
function page(slug,title,description,body,{noindex=false,scripts=[]}={}){
 const p='../'.repeat(slug.split('/').filter(Boolean).length)||'./';
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} | Hamperia Solutions</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="https://hamperiasolutions.com/${slug?slug+'/':''}">${noindex?'<meta name="robots" content="noindex,follow">':''}<meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:image" content="https://hamperiasolutions.com/assets/home_page.jpeg"><link rel="stylesheet" href="${p}css/style.css"><link rel="stylesheet" href="${p}css/branding.css"><link rel="stylesheet" href="${p}css/auth.css"><link rel="stylesheet" href="${p}css/storefront.css"><script src="${p}js/main.js" defer></script><script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2" defer></script><script src="${p}js/auth.js" defer></script><script src="${p}js/storefront.js" defer></script>${scripts.map(s=>'<script src="'+p+'js/'+s+'" defer></script>').join('')}</head><body><a class="skip" href="#main">Skip to content</a>${header(p)}<main id="main">${body.includes('data-auth-status') ? '' : '<p class="auth-status wrap" data-auth-status role="status"></p>'}${body}</main>${footer(p)}</body></html>`;
}
const intro=(title,description,p='../',parent)=>`<section class="wrap collection-intro"><p class="eyebrow"><a href="${p}">Home</a>${parent ? ` / <a href="${p}${parent.slug}/">${esc(parent.title)}</a>` : ''} / ${esc(title)}</p><h1>${esc(title)}</h1><p>${esc(description)}</p></section>`;
const productKind=(category)=>category==='hamper'?'Personalised hamper':category==='kit'?'Employee welcome kit':'Hamper-making supply';
const isProductArt=(image)=>/^(welcome-kit-|diwali-)/.test(image);
const card=(item,p='../')=>`<article class="shop-card" data-product-card data-product-slug="${item.slug}" data-name="${esc(item.name.toLowerCase())}" data-price="${item.price}" data-category="${item.category}"><a href="${p}products/${item.slug}/"><span class="shop-card-image"><img class="${isProductArt(item.image)?'product-art':''}" src="${p}assets/${item.image}" alt="${esc(item.name)} — product and included items shown" loading="lazy" width="600" height="500"></span><div class="shop-card-body"><span class="eyebrow">${productKind(item.category)}</span><h3>${esc(item.name)}</h3><p data-product-price>₹${item.price.toLocaleString('en-IN')} </p><span class="shop-card-link">View details ↗</span></div></a><div class="commerce-actions"><button class="wish-button" type="button" data-wish-key="catalog:${item.slug}" data-product-name="${esc(item.name)}" aria-label="Add to wishlist: ${esc(item.name)}" aria-pressed="false">♡</button><button class="add-button" type="button" data-cart-key="catalog:${item.slug}">Add to cart</button></div></article>`;
const cards=(items,p='../',catalog=false)=>`<div class="shop-grid"${catalog?' data-catalog-grid':''}>`+items.map(x=>x.slug.startsWith('dry-fruit-') ? card(x,p).replace('<span class="shop-card-link">','<small data-product-stock>10 available</small><span class="shop-card-link">') : card(x,p)).join('')+'</div>';
const quote=(topic,p='../')=>p+'bulk-orders/?collection='+encodeURIComponent(topic);
