function collectionExtras(c) {
 if (c.slug === 'corporate-merchandise') {
  const names=['Water bottles','Tumblers','Mugs','Keychains','T-shirts','Hoodies'];
  return `<section class="wrap section collection-feature"><div><p class="eyebrow">Brand it your way</p><h2>Everyday merchandise, made yours.</h2><p>Choose the items, colours and logo placement. We will confirm print method, minimum quantity and a sample before production.</p><a class="button secondary" href="${quote('Corporate merchandise')}">Request a merchandise quote</a></div><img src="../assets/corporate-merchandise-concept.png" alt="Bottle, tumbler, mug, keychain, T-shirt and hoodie merchandise examples" loading="lazy" width="600" height="600"></section><section class="wrap merch-grid" aria-label="Merchandise options">${names.map((name,i)=>`<article class="merch-tile" data-collection-example><div class="merch-crop merch-crop-${i+1}" aria-hidden="true"></div><h3>${name}</h3><p>Custom logo options · Price on request</p></article>`).join('')}</section>`;
 }
 if (c.slug === 'chocolate-hampers' || c.slug === 'wellness-hampers') {
  const chocolate = c.slug === 'chocolate-hampers';
  const image = chocolate ? 'chocolate-hamper-concept.png' : 'wellness-hamper-concept.png';
  const title = chocolate ? 'Build a box around their favourite chocolates.' : 'A quiet moment, beautifully boxed.';
  const detail = chocolate ? 'Choose chocolate styles, wrapping and a personal note. We will confirm the exact assortment, allergens, transit suitability and price in a custom quote.' : 'Combine a candle, a comforting drink, a journal or other calming touches. Fragrance preferences, final contents and price are confirmed in a custom quote.';
  return `<section class="wrap section collection-feature"><div><p class="eyebrow">Made for your recipient · Price on request</p><h2>${title}</h2><p>${detail}</p><a class="button secondary" href="${quote(c.title)}">Plan this hamper ↗</a></div><img src="../assets/${image}" alt="Illustrative ${c.title.toLowerCase()} concept" loading="lazy" width="600" height="600"></section>`;
 }
 const images=collectionImages[c.slug];
 return images ? `<section class="wrap section collection-gallery"><div class="section-heading"><div><p class="eyebrow">See the possibilities</p><h2>${c.slug === 'dry-fruit-hampers' ? 'Choose your box size.' : 'Thoughtful details, in every gift.'}</h2></div><p>Illustrative product photography. Check the product page and confirm final contents before payment.</p></div><div class="collection-gallery-grid">${images.map(([image,alt])=>`<img src="../assets/${image}" alt="${esc(alt)}" loading="lazy" width="500" height="500">`).join('')}</div></section>` : '';
}
function collectionBody(c) {
 const items=products.filter(x=>c.limit?x.price<c.limit:x.tags.includes(c.slug));
 const ideas=(inspirationExamples[c.slug]||[]).slice(0,Math.max(0,3-items.length));
 const ideaCards=ideas.length?`<div class="shop-grid inspiration-grid">${ideas.map(([image,title,description])=>`<article class="shop-card inspiration-card" data-collection-example><img src="../assets/${image}" alt="Illustrative ${esc(title)}" loading="lazy" width="600" height="500"><div class="shop-card-body"><span class="eyebrow">Made-to-order idea · Price on request</span><h3>${esc(title)}</h3><p>${esc(description)} Final contents, price and availability are confirmed in your quote.</p><a class="shop-card-link" href="${quote(title)}">Enquire about this idea ↗</a></div></article>`).join('')}</div>`:'';
 return intro(c.title,c.intro,'../',{slug:'corporate-bulk-gifting',title:'Corporate & Bulk Gifting'})+`<section class="wrap collection-story"><div><p class="eyebrow">Thoughtfully selected</p><h2>${esc(c.heading)}</h2><p>${esc(c.advice)}</p><p>${esc(c.planning)}</p><a class="button" href="${quote(c.title)}">Request a bulk quote ↗</a></div><aside><h3>Plan your gift</h3><ul>${c.features.map(f=>'<li>'+esc(f)+'</li>').join('')}</ul><p>Contents, availability, personalisation and delivery are confirmed before ordering.</p></aside></section>${collectionExtras(c)}<section class="wrap section" data-collection-slug="${c.slug}"><div class="section-heading"><h2>${items.length?'Explore the collection':'Explore the possibilities'}</h2><p>${items.length?'Listed product prices. Images show presentation inspiration.':'Made-to-order ideas are shown below. Request a quote to confirm contents, price and availability.'}</p></div>${cards(items,'../',true)}${ideaCards}${!items.length&&!ideas.length?'<a class="button secondary" href="'+quote(c.title)+'">Discuss your requirements</a>':''}</section><section class="wrap faq"><h2>Before you order</h2><details><summary>${esc(c.question)}</summary><p>${esc(c.answer)}</p></details><details><summary>How do I confirm my order?</summary><p>Send an enquiry with quantity, required date and delivery location. Review the final contents and quotation before confirming. Use the basket for listed products when checkout is available. Custom requests require a separate quote.</p></details><p><a href="../corporate-bulk-gifting/">Explore all corporate collections →</a> · <a href="../blog/corporate-gifting-planning-checklist/">Read the gifting checklist →</a></p></section>`;
}
